import secrets, string

def gerar_senha(tamanho=16):
    if tamanho < 8:
        raise ValueError("use pelo menos 8 caracteres")

    grupos = [string.ascii_lowercase, string.ascii_uppercase, string.digits, "!@#$%&*?"]
    alfabeto = "".join(grupos)

    while True:
        senha = "".join(secrets.choice(alfabeto) for _ in range(tamanho))
        if all(any(c in grupo for c in senha) for grupo in grupos):
            return senha

