import hashlib, hmac

def impressao(caminho, bloco=65536):
    h = hashlib.sha256()
    with open(caminho, "rb") as arquivo:
        while pedaco := arquivo.read(bloco):
            h.update(pedaco)
    return h.hexdigest()

def confere(caminho, esperado):
    return hmac.compare_digest(impressao(caminho), esperado.strip().lower())

