from collections import deque

class Limitador:
    def __init__(self, maximo=5, janela=60):
        self.maximo, self.janela = maximo, janela
        self.marcas = {}

    def permitido(self, chave, agora):
        fila = self.marcas.setdefault(chave, deque())
        while fila and agora - fila[0] > self.janela:
            fila.popleft()                 # saiu da janela, não conta mais
        if len(fila) >= self.maximo:
            return False
        fila.append(agora)
        return True

