def paginar(itens, pagina=1, por_pagina=20):
    if pagina < 1 or por_pagina < 1:
        raise ValueError("pagina e por_pagina começam em 1")

    inicio = (pagina - 1) * por_pagina
    total = len(itens)
    return {
        "itens": itens[inicio:inicio + por_pagina],
        "total": total,
        "pagina": pagina,
        "paginas": max(1, -(-total // por_pagina)),   # divisão arredondada pra cima
    }

