def validar(corpo, regras):
    if not isinstance(corpo, dict):
        return ["corpo: esperava um objeto"]

    erros = []
    for campo, regra in regras.items():
        if campo not in corpo:
            if regra.get("obrigatorio"):
                erros.append(f"{campo}: obrigatório")
            continue

        valor = corpo[campo]
        if type(valor) is not regra["tipo"]:      # tipo exato: True não passa por int
            erros.append(f"{campo}: esperava {regra['tipo'].__name__}")
            continue

        if regra["tipo"] is str:
            tamanho = len(valor.strip())
            if not regra.get("min", 0) <= tamanho <= regra.get("max", 10**9):
                erros.append(f"{campo}: entre {regra.get('min', 0)} e {regra.get('max')} caracteres")

    return erros

