def criar_registrador():
    feitos = {}

    def aplicar(chave, funcao):
        if chave in feitos:
            return feitos[chave], True        # repetido: devolve o mesmo de antes
        resultado = funcao()
        feitos[chave] = resultado
        return resultado, False

    return aplicar

