def por_cursor(itens, depois_de=None, tamanho=3):
    ordenados = sorted(itens, key=lambda i: i["id"])
    if depois_de is not None:
        ordenados = [i for i in ordenados if i["id"] > depois_de]

    pagina = ordenados[:tamanho]
    return {
        "itens": pagina,
        "proximo": pagina[-1]["id"] if len(ordenados) > tamanho else None,
    }

